using System.Data;using System.Data.Common;using AiCare.Application;using AiCare.Domain;using AiCare.Infrastructure;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;using Microsoft.EntityFrameworkCore.Storage;
namespace AiCare.Api;
[ApiController,Authorize(Roles="Administrator,BackOffice")][Route("api/phase1/finance/accounting")]
public sealed class AccountingIntegrationController(CareDbContext db,ITenantContext tenant,ICurrentUserContext user):ControllerBase
{
 Guid Branch=>tenant.BranchId??TenantDefaults.BranchId;
 [HttpGet("connections")]public async Task<IActionResult>Connections(CancellationToken t)=>Ok(await Rows("select id,provider,status,external_tenant_id,connected_at,last_refreshed_at,disconnected_at from accounting_connections where organization_id=@org order by provider",_=>{},t));
 [HttpPost("connections")]public async Task<IActionResult>Connect(AccountingConnectionRequest r,CancellationToken t){if(r.Provider is not ("Sage" or "Xero" or "QuickBooks" or "Manual")||string.IsNullOrWhiteSpace(r.ExternalTenantId)||string.IsNullOrWhiteSpace(r.CredentialReference))return BadRequest(new{message="Provider, external tenant, and secret-store credential reference are required."});var id=Guid.NewGuid();await Exec("insert into accounting_connections(id,organization_id,provider,status,external_tenant_id,credential_reference,connected_by) values(@id,@org,@provider,'Active',@tenant,@credential,@actor) on conflict(organization_id,provider) do update set status='Active',external_tenant_id=excluded.external_tenant_id,credential_reference=excluded.credential_reference,connected_at=now(),connected_by=@actor,disconnected_at=null",c=>{Add(c,"id",id);Add(c,"provider",r.Provider);Add(c,"tenant",r.ExternalTenantId.Trim());Add(c,"credential",r.CredentialReference.Trim());},t);Audit("ACCOUNTING_CONNECTED",id);await db.SaveChangesAsync(t);return NoContent();}
 [HttpPost("connections/{provider}/disconnect")]public async Task<IActionResult>Disconnect(string provider,CancellationToken t){var changed=await Exec("update accounting_connections set status='Disconnected',disconnected_at=now() where organization_id=@org and provider=@provider and status='Active'",c=>Add(c,"provider",provider),t);if(changed==0)return NotFound();Audit("ACCOUNTING_DISCONNECTED",null);await db.SaveChangesAsync(t);return NoContent();}
 [HttpPost("enqueue")]public async Task<IActionResult>Enqueue(AccountingEnqueueRequest r,CancellationToken t){if(r.EntityId==Guid.Empty||r.EntityType is not ("Funder" or "Invoice" or "CreditNote" or "Payment"))return BadRequest(new{message="Supported entity is required."});var provider=await Text("select provider from accounting_connections where organization_id=@org and status='Active' order by connected_at desc limit 1",_=>{},t);if(provider is null)return Conflict(new{message="No active accounting connection exists."});var id=Guid.NewGuid();try{await Exec("insert into accounting_outbox(id,organization_id,provider,entity_type,entity_id,operation,idempotency_key) values(@id,@org,@provider,@type,@entity,@operation,@key)",c=>{Add(c,"id",id);Add(c,"provider",provider);Add(c,"type",r.EntityType);Add(c,"entity",r.EntityId);Add(c,"operation",r.Operation);Add(c,"key",r.IdempotencyKey);},t);}catch(Npgsql.PostgresException e)when(e.SqlState==Npgsql.PostgresErrorCodes.UniqueViolation){return Ok(new{status="AlreadyQueued"});}return Accepted(new{id,status="Pending"});}
 [HttpGet("outbox")]public async Task<IActionResult>Outbox(CancellationToken t)=>Ok(await Rows("select id,provider,entity_type,entity_id,operation,status,attempt_count,last_attempt_at,last_success_at,sanitized_error,created_at from accounting_outbox where organization_id=@org order by created_at desc",_=>{},t));
 async Task<string?>Text(string s,Action<DbCommand>b,CancellationToken t){await using var c=await Cmd(s,t);b(c);return Convert.ToString(await c.ExecuteScalarAsync(t));}async Task<List<Dictionary<string,object?>>>Rows(string s,Action<DbCommand>b,CancellationToken t){var a=new List<Dictionary<string,object?>>();await using var c=await Cmd(s,t);b(c);await using var r=await c.ExecuteReaderAsync(t);while(await r.ReadAsync(t)){var d=new Dictionary<string,object?>();for(var i=0;i<r.FieldCount;i++)d[r.GetName(i)]=r.IsDBNull(i)?null:r.GetValue(i);a.Add(d);}return a;}async Task<int>Exec(string s,Action<DbCommand>b,CancellationToken t){await using var c=await Cmd(s,t);b(c);return await c.ExecuteNonQueryAsync(t);}async Task<DbCommand>Cmd(string s,CancellationToken t){var n=db.Database.GetDbConnection();if(n.State!=ConnectionState.Open)await n.OpenAsync(t);var c=n.CreateCommand();c.Transaction=db.Database.CurrentTransaction?.GetDbTransaction();c.CommandText=s;Add(c,"org",tenant.OrganizationId);Add(c,"actor",user.UserName);return c;}static void Add(DbCommand c,string n,object?v){if(c.Parameters.Contains(n))return;var p=c.CreateParameter();p.ParameterName=n;p.Value=v??DBNull.Value;c.Parameters.Add(p);}void Audit(string a,Guid?id)=>db.AuditEvents.Add(new AuditEvent(Guid.NewGuid(),a,user.UserName,"AccountingConnection",id,DateTimeOffset.UtcNow,tenant.OrganizationId,Branch));
}
public sealed record AccountingConnectionRequest(string Provider,string ExternalTenantId,string CredentialReference);public sealed record AccountingEnqueueRequest(string EntityType,Guid EntityId,string Operation,string IdempotencyKey);
